/**
 * 03-capture-actions.js
 *
 * Capture, step creation, duplication, and basic export helpers. Capture reads current DOM controls back into state before save/export/autosave operations.
 * Auto-generated documentation comments explain function purpose, expected inputs, and module sections without changing runtime behavior.
 */

// -----------------------------------------------------------------------------
// DOM-to-state capture
// -----------------------------------------------------------------------------
/**
 * Reads current DOM controls into the in-memory audit state.
 */
function capture() {
  state.audit.name = e.auditName.value || "Untitled Audit";
  state.audit.purpose = e.auditPurpose.value || "";
  if (e.auditStatus) state.audit.status = e.auditStatus.value || "Draft";
  document.querySelectorAll(".selected-source-card").forEach((card) => {
    const source = state.audit.sources.find(
      (item) => item.id === card.dataset.id,
    );
    if (source)
      source.color =
        card.querySelector("[data-source-color]")?.value ||
        source.color ||
        SOURCE_COLOR_PALETTE[0];
  });
  document.querySelectorAll(".step-card").forEach((card) => {
    const step = state.audit.steps.find((item) => item.id === card.dataset.id);
    if (!step) return;
    if (step.autoGeneratedReference) return;
    step.parentId = card.querySelector("[data-step-parent]")?.value || null;
    step.branchType = step.parentId
      ? card.querySelector("[data-step-branch]")?.value || "then"
      : "root";
    step.sortOrder = Number(step.sortOrder ?? state.audit.steps.indexOf(step));
    step.title =
      card.querySelector("[data-step-title]")?.value ||
      step.title ||
      "Logic Step";
    step.type =
      card.querySelector("[data-step-type]")?.value || step.type || "if";
    step.source =
      card.querySelector("[data-step-source]")?.value || step.source || "";
    step.field =
      card.querySelector("[data-step-field]")?.value || step.field || "";
    step.action =
      card.querySelector("[data-step-action]")?.value || step.action || "";
    step.notes = card.querySelector("[data-step-notes]")?.value || "";
    step.enabled = card.querySelector("[data-step-enabled]")?.checked ?? true;
  });
}

// -----------------------------------------------------------------------------
// Step actions
// -----------------------------------------------------------------------------
/**
 * Adds a new top-level IF/THEN step.
 */
function addStep() {
  capture();
  const step = {
    id: uid("step"),
    enabled: true,
    parentId: null,
    branchType: "root",
    sortOrder: state.audit.steps.length + 1,
    title: "IF / THEN",
    type: "if",
    step_type: "if_then",
    source: state.audit.sources[0]?.name || "",
    field: "",
    action: "",
    notes: "",
    conditions: [
      { id: uid("cond"), field: "", operator: "is equal to", value: "" },
    ],
    params: {},
  };
  state.audit.steps.push(step);
  state.selectedStepId = step.id;
  renderAll();
  showSection("steps");
  scheduleAutosave();
}

/**
 * Returns the currently selected step object.
 */
function selectedStep() {
  return state.audit.steps.find((step) => step.id === state.selectedStepId);
}

// -----------------------------------------------------------------------------
// Basic exports
// -----------------------------------------------------------------------------
/**
 * Exports the current audit as JSON.
 */
function exportCurrent() {
  capture();
  downloadJson(
    `${state.audit.name.replace(/[^A-Za-z0-9_-]+/g, "_") || "audit_logic"}.json`,
    state.audit,
  );
}

/**
 * Exports preview rows as CSV.
 */
function exportCsv() {
  const rows = previewRows();
  const csv = [
    "Step,Analyst Logic,Developer Logic,Notes",
    ...rows.map((row) =>
      [row.step, row.analyst, row.developer, row.notes]
        .map(csvEscape)
        .join(","),
    ),
  ].join("\n");
  downloadBlob(`audit_logic_${today()}.csv`, csv, "text/csv");
}

/**
 * Copies the Markdown export to the clipboard.
 */
function copyMarkdown() {
  navigator.clipboard?.writeText(markdown());
  status("Markdown copied to clipboard.", "ok");
}

// ATLAS-MATH-OPERATIONS-UPDATE:BEGIN
markdown = function markdownWithDeveloperLogic() {
  const clean = (value) =>
    String(value || "")
      .replace(/\|/g, "\\|")
      .replace(/\r?\n/g, "<br>");
  const rows = previewRows();
  return [
    "| Step | Analyst Logic | Developer Logic | Notes |",
    "|---|---|---|---|",
    ...rows.map(
      (row) =>
        `| ${clean(row.step)} | ${clean(row.analyst)} | ${clean(row.developer)} | ${clean(row.notes)} |`,
    ),
  ].join("\n");
};
// ATLAS-MATH-OPERATIONS-UPDATE:END
